{
  "restricciones": [
    {
      "id": "R1",
      "cumple": true,
      "evidencia": "Se adopta un monolito modular en capas (API → Servicio de dominio → Repositorio) construido con FastAPI y PostgreSQL."
    },
    {
      "id": "R2",
      "cumple": true,
      "evidencia": "La base de datos PostgreSQL existente es la única base de datos; no se agregan otras (ni Redis ni bases NoSQL)."
    },
    {
      "id": "R3",
      "cumple": true,
      "evidencia": "Sin colas ni brokers de mensajes (Kafka, RabbitMQ, Amazon SQS, Celery). La detección de precios se ejecuta como tarea interna (APScheduler)."
    },
    {
      "id": "R4",
      "cumple": true,
      "evidencia": "Los correos se envían solo mediante el servicio interno existente: POST /internal/mail/send con JSON {to, subject, body}."
    },
    {
      "id": "R5",
      "cumple": true,
      "evidencia": "La detección de bajas de precio se ejecuta como tarea programada cada hora dentro de la misma aplicación (Price Detection Scheduler)."
    },
    {
      "id": "R6",
      "cumple": true,
      "evidencia": "No se contratan ni integran servicios de terceros nuevos; todo se basa en componentes internos existentes."
    }
  ],
  "specs": [
    {
      "id": "SPEC-01",
      "cubierto": true,
      "evidencia": "Wishlist API Controller (ARCH-01) y Wishlist Service (ARCH-02) manejan agregar producto, validan duplicados y límite de 50, guardan precio vigente."
    },
    {
      "id": "SPEC-02",
      "cubierto": true,
      "evidencia": "Endpoint /wishlist/remove y método remove_item en ARCH-02 eliminan producto; devuelven error si no estaba."
    },
    {
      "id": "SPEC-03",
      "cubierto": true,
      "evidencia": "Endpoint /wishlist devuelve items ordenados por added_at ASC con saved_price y current_price (ARCH-02, ARCH-04)."
    },
    {
      "id": "SPEC-04",
      "cubierto": true,
      "evidencia": "Price Detection Scheduler (ARCH-03) compara precio guardado vs actual, aplica umbral configurable (ARCH-06) y detecta bajas >= umbral."
    },
    {
      "id": "SPEC-05",
      "cubierto": true,
      "evidencia": "Mail Client (ARCH-05) envía correo vía /internal/mail/send; scheduler verifica límite de 1 aviso por cliente‑producto cada 24 h."
    },
    {
      "id": "SPEC-06",
      "cubierto": true,
      "evidencia": "Endpoint /wishlist/status (opcional) devuelve enabled=false y mensaje 'Inicia sesión para usar tu lista de deseos' para invitados (ARCH-01)."
    }
  ],
  "funcionalidades_inventadas": [],
  "datos_inventados": [],
  "contratos_completos": true,
  "puntaje_revision": 10,
  "justificacion": "La arquitectura cumple todas las restricciones técnicas, cubre completamente los seis requisitos funcionales, define contratos claros con entradas, salidas y errores, y no introduce funcionalidades ni datos inventados."
}
